 <button className="workspace" onClick={()=>togglePopup('"'workspace')} title={workspace}><span className=\"store-icon\"><Icon name=\"box\" size={19}/></span>{"'!collapsed&&<><span><strong>{workspace}</strong><small>Рабочее пространство</small></span><Icon name="chevron" size={13}/></>}</button>
 {popup==='"'workspace'&&<div className=\"workspace-pop floating\"><strong>{workspace}</strong><p>Ваше рабочее пространство</p><button onClick={()=>{setSection('Настройки');setPopup(null)}}>Настроить магазин <Icon name=\"settings\" size={15}/></button></div>}
 {"'!collapsed&&<div className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div>}
