 {(section==='Заказы'||section==='Главная')&&<><div className=\"metrics\">{[{title:'Всего заказов',value:String(orders.length),icon:'orders',change:'+12,8%',note:'за этот месяц',color:'neutral'}, {title:'В обработке',value:String(orders.filter(o=>o.status==='processing').length),icon:'clock',change:'+4',note:'сегодня',color:'orange'}, {title:'Выполнено',value:String(orders.filter(o=>o.status==='done').length),icon:'check',change:'+18,6%',note:'за этот месяц',color:'green'}, {title:'Выручка',value:money(orders.filter(o=>o.payment==='Оплачен').reduce((sum,o)=>sum+o.amount,0)),icon:'wallet',change:'+8,2%',note:'за этот месяц',color:'purple'}].map((metric,i)=><div className=\"metric-card\" key={metric.title}><div className=\"metric-top\"><span>{metric.title}</span><span className={"'`metric-icon ${metric.color}`}><Icon name={metric.icon as IconName} size={18}/></span></div><div className="metric-value">{metric.value}<svg className={`sparkline spark-${i}`} viewBox="0 0 90 32"><path d={['"'M1 29 12 21 22 25 33 14 44 19 56 10 67 13 79 3 89 6','M1 22 12 26 22 18 33 21 44 11 56 17 67 7 79 13 89 6','M1 29 12 24 22 27 33 16 44 20 56 9 67 13 79 4 89 7','M1 27 12 20 22 24 33 13 44 17 56 6 67 12 79 4 89 7'][i]} fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg></div><div className=\"metric-foot\"><span className={i===1?'change-orange':'change-green'}><Icon name=\"arrow\" size={12}/>{metric.change}</span><span>{metric.note}</span></div></div>)}</div></>}
