const { chromium } = require('playwright');
const assert = require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1440,height:1080},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:5175');await page.evaluate(()=>document.fonts.ready);await page.screenshot({path:'/tmp/orbit-desktop.png',fullPage:true});
 assert.equal(await page.locator('.order-row').count(),9);
 assert.equal(await page.locator('.group-row').count(),3);
 await page.getByLabel('Выбрать все заказы на странице').check();
 assert.match(await page.locator('.selection-bar').innerText(),/Выбрано: 9/);
 await page.getByTitle('Снять выделение').click();
 await page.getByLabel('Поиск заказов').fill('Мария');
 assert.equal(await page.locator('.order-row').count(),4);
 await page.getByTitle('Очистить поиск').click();
 await page.getByRole('button',{name:'По статусу',exact:true}).click();
 await page.getByRole('button',{name:'Без группировки',exact:true}).click();
 assert.equal(await page.locator('.group-row').count(),0);
 await page.getByRole('button',{name:'Без группировки',exact:true}).click();
 await page.getByRole('button',{name:'По статусу заказа',exact:true}).click();
 await page.locator('.group-row button').first().click();assert.equal(await page.locator('.order-row').count(),6);
 await page.locator('.group-row button').first().click();
 await page.locator('th.col-amount').dragTo(page.locator('th.col-customer'));
 assert.equal(await page.locator('thead th').nth(2).getAttribute('class'),' col-amount');
 await page.getByRole('button',{name:'Колонки',exact:true}).click();
 await page.locator('.columns-pop').getByLabel('Оплата',{exact:true}).uncheck();assert.equal(await page.locator('th.col-payment').count(),0);
 await page.locator('.columns-pop').getByRole('button',{name:'Сбросить настройки'}).click();
 await page.getByRole('button',{name:'Колонки',exact:true}).click();
 await page.getByRole('button',{name:'Создать заказ',exact:true}).click();
